"""specs_s200031.py - Sonnet-w2 family H (generated by mkfamH.py). 0x48c4b0 (stdcall) fills the first 0x60 bytes of the stack-local L with random bytes (the frame cookie and SEH record live above ebp-0x14, so never fill the whole 0x90) (L recorded as a stack marker); 0x4cc1d0 returns [L] like
the real code; the slot 0x30 stub of the object at [0x700394] and 0x4cbec0 read L back (first 16 bytes) into the call log; the /GS check 0x633654 is a recorder (ecx = the global cookie)
that preserves eax. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _gen(c):
    clear_hooks(c)
    seh_chain(c, c.rng.choice([0, 1, 2]))
    r = c.rng
    sr1, sr2, sr3 = seh_record(c, 2), seh_record(c, 2), seh_record(c, 2)

    def fill(emu, k):
        a = emu.arg32(0)
        emu.wbytes(a, bytes(r.getrandbits(8) for _ in range(0x60)))
        sr1(emu, k)

    def slot_side(emu, k):
        emu.calllog.append(('arg', emu.arg32(0), emu.arg32(1)))
        sr2(emu, k)

    def dtor_side(emu, k):
        a = emu.reg('ecx')
        emu.calllog.append(('L', emu.rbytes(a, 16).hex()))
        sr3(emu, k)
    hook_rec(c, 0x48c4b0, 2, ret=r.getrandbits(32), pop=8, stackmark=(0,), side=fill)
    hook_rec(c, 0x4cc1d0, 0, ret=lambda emu, k: emu.r32(emu.reg('ecx')), this='mark')
    hook_rec(c, 0x4cbec0, 0, ret=r.getrandbits(32), this='mark', side=dtor_side)
    hook_rec(c, 0x633654, 0, ret=lambda emu, k: emu.reg('eax'), pop=0, this=True)
    g = obj(c, 0x40, {0x30: pystub(c, 2, ret=r.getrandbits(32), this=True, side=slot_side)}, nslots=0x20)
    c.emu.w32(0x700394, g)
    return []


S(0x490470, 'GUESS famH 0x490470', 'cdecl', None, ret='eax', gen=_gen, note='batch200031')
S(0x4905c0, 'GUESS famH 0x4905c0', 'cdecl', None, ret='eax', gen=_gen, note='batch200031')
